def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive_opponents = []
    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0

    for opp_id, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        alive_opponents.append(opp)
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opponents += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    if not alive_opponents:
        if hp <= 3 or no_water >= 1:
            return min(budget, 28)
        return min(budget, 12)

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    base = DAILY_SALARY * (0.34 + 0.26 * scarcity)

    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.92)
    elif hp <= 4 or no_water >= 1:
        base = max(base, DAILY_SALARY * 0.72)
    elif hp >= 8 and no_water == 0 and supply >= 22:
        base = min(base, DAILY_SALARY * 0.28)

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        target = max(avg_prev + 1.0, highest_prev + 1.5 * scarcity)
        if hp <= 4 or no_water >= 1:
            base = max(base, target)
        else:
            base = max(base, min(target, DAILY_SALARY * 0.78))

    if urgent_opponents > 0 and supply <= 18:
        base += 4
    if rich_opponents >= 2 and supply <= 17:
        base += 3

    remaining_days = max(1, 10 - int(day_context['day']) + 1)
    reserve_floor = DAILY_SALARY * 0.18 * remaining_days
    cap = budget
    if budget > reserve_floor:
        cap = budget - max(0, reserve_floor * 0.15)

    if hp <= 2:
        cap = budget

    bid = min(base, cap)
    if bid < 0:
        bid = 0
    if bid > budget:
        bid = budget
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))

    alive_opponents = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((opp_id, o))

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids for immediate reaction
    prev_bids = []
    for _, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Supply pressure factor: closer to min supply -> higher chance of competition
    # Use safe index-free math; only indices would need int() (none used).
    supply_mid = (MAX_SUPPLY + MIN_SUPPLY) / 2.0
    competition = 0.55
    if supply <= supply_mid:
        competition = 0.75
    elif supply >= MAX_SUPPLY:
        competition = 0.5

    aggressive_threshold = DAILY_SALARY * 0.85

    # Baseline bid: aim for at least one unit of water requirement share, scaled by competition
    # We cannot directly buy water; bid is the proxy.
    base_bid = DAILY_SALARY * (0.45 + 0.25 * competition)

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If someone was aggressive yesterday, we counter just enough.
        if highest_prev_bid >= aggressive_threshold:
            # If our hp is low, we must secure water more strongly.
            if my_hp <= 2:
                bid = DAILY_SALARY * 0.95
            elif my_hp <= 4:
                bid = DAILY_SALARY * 0.75
            else:
                bid = DAILY_SALARY * 0.62
            # Outbid slightly to beat their likely continuation, but cap by our budget.
            bid = max(bid, highest_prev_bid + 1.0)
        else:
            # If they weren't aggressive, don't overpay; bid near base, slightly above their max.
            bid = max(base_bid, highest_prev_bid + 0.5)
    else:
        bid = base_bid

    # Final risk controls
    # If our hp is critical, push harder; otherwise conserve.
    if my_hp <= 1:
        bid = max(bid, DAILY_SALARY * 0.9)
    elif my_hp <= 3:
        bid = max(bid, DAILY_SALARY * 0.7)
    else:
        # If we have plenty of hp, avoid unnecessary escalation late in episode.
        if day >= 7:
            bid = min(bid, DAILY_SALARY * 0.6)

    # Budget cap
    if my_budget <= 0:
        return 0.0
    if bid > my_budget:
        bid = my_budget

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

